SELECT u.id AS user_id, p.id AS post_id, u.nickname, u.birth_year, u.gender, u.country, u.is_premium, p.one_liner, p.published_at, COALESCE(ps.exposures, 0) AS exposures, COALESCE(ps.likes, 0) AS likes, COALESCE(ps.requests, 0) AS requests FROM posts p JOIN users u ON u.id = p.user_id LEFT JOIN post_stats ps ON ps.user_id = u.id AND ps.session_date = #{sessionDate} WHERE p.session_date = #{sessionDate} AND p.published_at IS NOT NULL AND u.id != #{userId} AND u.status = 'ACTIVE' AND NOT EXISTS (SELECT 1 FROM blocks b WHERE (b.blocker_id = #{userId} AND b.blocked_id = u.id) OR (b.blocker_id = u.id AND b.blocked_id = #{userId})) AND NOT EXISTS (SELECT 1 FROM reports r WHERE (r.reporter_id = #{userId} AND r.target_id = u.id) OR (r.reporter_id = u.id AND r.target_id = #{userId})) AND NOT EXISTS (SELECT 1 FROM feed_skips s WHERE s.user_id = #{userId} AND s.target_user_id = u.id AND s.session_date = #{sessionDate}) AND u.gender = #{gender} AND u.country = #{country}
AND (YEAR(CURDATE()) - u.birth_year) BETWEEN #{ageMin} AND #{ageMax}
AND u.is_premium = 1

SELECT EXISTS (
    SELECT 1 FROM daily_translate_targets
    WHERE user_id = #{userId}
      AND session_date = #{sessionDate}
      AND target_id = #{targetId}
)
